#:property PublishAot=false

// original.cs — a working todo API where EVERYTHING lives in endpoint lambdas.
// It serves correctly if you run it. It is also a nightmare to change:
// the same find-by-id loop appears four times, the same title validation
// twice, and no test can reach any of the logic without booting a server.
//
// Run:   dotnet run csharp/15-minimal-api-todo/original.cs
// Then:  curl http://localhost:5015/todos

using System.Text.Json;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// The "database": a list of dictionaries. Nothing anywhere says what a todo
// looks like — every endpoint just has to *know* the keys and cast the values.
var todos = new List<Dictionary<string, object>>();

app.MapGet("/todos", (HttpRequest req) =>
{
    // filtering logic, inline in the endpoint
    string? filter = req.Query["filter"];
    var result = new List<Dictionary<string, object>>();
    foreach (var t in todos)
    {
        if (filter == "done" && !(bool)t["done"]) continue;
        if (filter == "open" && (bool)t["done"]) continue;
        result.Add(t);
    }
    return Results.Json(result);
});

app.MapGet("/todos/{id}", (int id) =>
{
    // find-by-id loop, copy #1
    Dictionary<string, object>? found = null;
    foreach (var t in todos)
        if ((int)t["id"] == id) found = t;
    if (found == null)
        return Results.Json(new Dictionary<string, object> { ["error"] = "no such todo" }, statusCode: 404);
    return Results.Json(found);
});

app.MapPost("/todos", (JsonElement body) =>
{
    // title validation, copy #1
    if (!body.TryGetProperty("title", out var titleProp) || titleProp.ValueKind != JsonValueKind.String)
        return Results.Json(new Dictionary<string, object> { ["error"] = "title is required" }, statusCode: 400);
    var title = titleProp.GetString()!;
    if (title.Trim().Length == 0)
        return Results.Json(new Dictionary<string, object> { ["error"] = "title must not be empty" }, statusCode: 400);

    // id generation, inline: scan the whole list for the biggest id
    var maxId = 0;
    foreach (var t in todos)
        if ((int)t["id"] > maxId) maxId = (int)t["id"];

    var todo = new Dictionary<string, object>
    {
        ["id"] = maxId + 1,
        ["title"] = title.Trim(),
        ["done"] = false,
    };
    todos.Add(todo);
    return Results.Json(todo, statusCode: 201);
});

app.MapPut("/todos/{id}", (int id, JsonElement body) =>
{
    // find-by-id loop, copy #2
    Dictionary<string, object>? found = null;
    foreach (var t in todos)
        if ((int)t["id"] == id) found = t;
    if (found == null)
        return Results.Json(new Dictionary<string, object> { ["error"] = "no such todo" }, statusCode: 404);

    // title validation, copy #2 — already drifting: this copy and the POST
    // copy must be kept in sync by hand, forever
    if (!body.TryGetProperty("title", out var titleProp) || titleProp.ValueKind != JsonValueKind.String)
        return Results.Json(new Dictionary<string, object> { ["error"] = "title is required" }, statusCode: 400);
    var title = titleProp.GetString()!;
    if (title.Trim().Length == 0)
        return Results.Json(new Dictionary<string, object> { ["error"] = "title must not be empty" }, statusCode: 400);

    found["title"] = title.Trim();
    if (body.TryGetProperty("done", out var doneProp))
        found["done"] = doneProp.ValueKind == JsonValueKind.True;
    return Results.Json(found);
});

app.MapPost("/todos/{id}/toggle", (int id) =>
{
    // find-by-id loop, copy #3
    Dictionary<string, object>? found = null;
    foreach (var t in todos)
        if ((int)t["id"] == id) found = t;
    if (found == null)
        return Results.Json(new Dictionary<string, object> { ["error"] = "no such todo" }, statusCode: 404);

    found["done"] = !(bool)found["done"];
    return Results.Json(found);
});

app.MapDelete("/todos/{id}", (int id) =>
{
    // find-by-id loop, copy #4
    Dictionary<string, object>? found = null;
    foreach (var t in todos)
        if ((int)t["id"] == id) found = t;
    if (found == null)
        return Results.Json(new Dictionary<string, object> { ["error"] = "no such todo" }, statusCode: 404);

    todos.Remove(found);
    return Results.Json(new Dictionary<string, object> { ["deleted"] = true });
});

app.Run("http://localhost:5015");

# 🏋️ Practice: Minimal API Todo

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. A stats endpoint (warm-up)

Add `GET /todos/stats` that answers `{"total":3,"done":1,"open":2}`. Put the counting in a new
`TodoService.Stats()` method returning a small record, so the endpoint stays a one-liner.
*Practices:* adding a route to a `MapGroup` + keeping the decision in the service.
**Hint:** LINQ's `Count(t => t.Done)` does the counting; a `record TodoStats(...)` states the shape once.
**Check offline:** add `Check.Equal(2, svc.Stats().Open, "two open after one toggle")` style tests — they
should pass — then `curl http://localhost:5015/todos/stats` → `200` with the three counts.

### ⭐⭐ 2. Search the list (core)

Let clients ask `GET /todos?q=milk` to get only todos whose title contains `q` (case-insensitive),
combinable with the existing filter: `?filter=open&q=milk`. Extend `Filter` to take a second parameter.
*Practices:* query-string binding with two optional parameters + a pure LINQ pipeline.
**Hint:** run the `switch` first, then apply `.Where(t => t.Title.Contains(q.Trim(), StringComparison.OrdinalIgnoreCase))` only when `q` has content.
**Check offline:** `Check.Equal(1, svc.Filter("open", "milk").Count, "search respects the filter")` should pass.

### ⭐⭐ 3. Duplicate a todo (core)

Add `POST /todos/{id}/duplicate`: it copies todo `id` into a brand-new todo titled `"<title> (copy)"`,
not done, with a fresh id, and answers `201 Created` (or `404` for an unknown id).
*Practices:* a new service method + translating its `Todo?` answer into 201/404.
**Hint:** mirror how `Toggle` is mapped; the service method reuses `Get(id)` and `_nextId++`.
**Check offline:** `curl -i -X POST http://localhost:5015/todos/1/duplicate` → `201`, `Location: /todos/2`;
`curl -i -X POST http://localhost:5015/todos/999/duplicate` → `404`.

### ⭐⭐ 4. Clear all finished todos (core)

Add `DELETE /todos/done` that removes every done todo at once and answers `200` with `{"removed":2}`.
The service method should return *how many* it removed.
*Practices:* a bulk operation + a route that must not collide with `DELETE /todos/{id:int}`.
**Hint:** `List<T>.RemoveAll(predicate)` already returns the count. `"done"` isn't an int, so the
`{id:int}` route can't swallow it.
**Check offline:** `Check.Equal(0, svc.ClearDone(), "nothing to clear on a fresh service")` passes; with a
server: toggle one todo, `curl -X DELETE http://localhost:5015/todos/done` → `{"removed":1}`.

### ⭐⭐⭐ 5. Reject duplicate titles — with the right error message (challenge)

Two different rejections ("blank title" vs "that title already exists", compared case-insensitively)
currently can't be told apart, because `Add` returns only `Todo?`. Introduce
`TryAdd(string? title)` returning `(Todo? Todo, string? Error)`, keep `Add` working by delegating to it
(so `Tests.cs` stays green), and make `POST /todos` echo the specific error in its 400 body.
*Practices:* the pure domain layer — evolving a service signature when `null` stops being informative.
**Hint:** tuple returns read like `var (todo, error) = service.TryAdd(body.Title);`.
**Check offline:** add this Check test — it should pass:
`Check.Equal("title must not be empty", svc.TryAdd("  ").Error, "blank keeps its own message");`
then POST the same title twice → second answer is `400` `{"error":"a todo titled '...' already exists"}`.

## Solutions

### 1. Stats endpoint

```csharp
// Todo.cs — one more shape
public record TodoStats(int Total, int Done, int Open);

// TodoService.cs
public TodoStats Stats() =>
    new(_todos.Count, _todos.Count(t => t.Done), _todos.Count(t => !t.Done));

// Program.cs (inside the group; a literal segment never clashes with {id:int})
todos.MapGet("/stats", () => service.Stats());
```

WHY: the counting is a *decision about the data*, so it lives in the service where a plain method call
can test it. The endpoint only forwards. `/todos/stats` and `/todos/{id:int}` coexist because `stats`
fails the `:int` constraint, so routing never confuses them.

### 2. Search

```csharp
// TodoService.cs — replaces Filter
public IReadOnlyList<Todo> Filter(string? filter, string? q = null)
{
    IEnumerable<Todo> result = filter switch
    {
        "done" => _todos.Where(t => t.Done),
        "open" => _todos.Where(t => !t.Done),
        _ => _todos,
    };
    if (!string.IsNullOrWhiteSpace(q))
        result = result.Where(t => t.Title.Contains(q.Trim(), StringComparison.OrdinalIgnoreCase));
    return result.ToList();
}

// Program.cs
todos.MapGet("/", (string? filter, string? q) => service.Filter(filter, q));
```

WHY: the default `q = null` keeps every existing caller (and test) compiling. Staying in
`IEnumerable<Todo>` until the final `ToList()` lets the two conditions *compose* instead of multiplying
into four branches — cs#04's pipeline idea. Binding gives us both query values for free.

### 3. Duplicate

```csharp
// TodoService.cs
/// Returns the fresh copy, or null when the source id is unknown.
public Todo? Duplicate(int id)
{
    var source = Get(id);
    if (source is null) return null;
    var copy = new Todo(_nextId++, $"{source.Title} (copy)", Done: false);
    _todos.Add(copy);
    return copy;
}

// Program.cs
todos.MapPost("/{id:int}/duplicate", (int id) =>
    service.Duplicate(id) is Todo t
        ? Results.Created($"/todos/{t.Id}", t)
        : Results.NotFound());
```

WHY: a duplicate is a *new resource*, so the honest reply is `201` with its address — the same
convention `POST /todos` already uses. Reusing `Get` keeps find-by-id in exactly one place, which was
the whole point of the refactor.

### 4. Clear finished

```csharp
// TodoService.cs
/// Removes every done todo; returns how many were removed.
public int ClearDone() => _todos.RemoveAll(t => t.Done);

// Program.cs — map this; "done" is not an int, so {id:int} never captures it
todos.MapDelete("/done", () => new { removed = service.ClearDone() });
```

WHY: `RemoveAll` returns the removal count, which is exactly the fact the client wants back, so the
service exposes it directly. We answer `200` with a body (not `204`) because there *is* something to
say. The `:int` constraint is what makes this route safe to add.

### 5. TryAdd with a reason

```csharp
// TodoService.cs
/// Returns (todo, null) on success, or (null, reason) explaining the rejection.
public (Todo? Todo, string? Error) TryAdd(string? title)
{
    if (string.IsNullOrWhiteSpace(title)) return (null, "title must not be empty");
    var trimmed = title.Trim();
    if (_todos.Any(t => string.Equals(t.Title, trimmed, StringComparison.OrdinalIgnoreCase)))
        return (null, $"a todo titled '{trimmed}' already exists");
    var todo = new Todo(_nextId++, trimmed, Done: false);
    _todos.Add(todo);
    return (todo, null);
}

/// Old signature, kept so existing callers and tests stay green.
public Todo? Add(string? title) => TryAdd(title).Todo;

// Program.cs
todos.MapPost("/", (CreateTodo body) =>
{
    var (todo, error) = service.TryAdd(body.Title);
    return todo is not null
        ? Results.Created($"/todos/{todo.Id}", todo)
        : Results.BadRequest(new { error });
});

// Tests.cs — new checks
var svc = new TodoService();
Check.Equal("title must not be empty", svc.TryAdd("  ").Error, "blank keeps its own message");
svc.TryAdd("buy milk");
Check.True(svc.TryAdd("BUY MILK").Error!.Contains("already exists"), "duplicates are named as such");
Check.Equal(1, svc.All().Count, "the duplicate was never added");
```

WHY: `Todo?` can say *no* but not *why* — with two rules that's no longer enough, so the signature
grows into a tiny Result tuple (cs#08's idea without a new type). Delegating `Add` to `TryAdd` keeps
one copy of the rules and zero broken tests, and the endpoint stays pure translation: it just forwards
whichever reason the domain produced.

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

// Program.cs — the thin HTTP layer. Every endpoint is one line of translation:
// HTTP in → service call → HTTP out. Nothing here is worth testing, because
// nothing here decides anything. The decisions live in TodoService.cs.

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var service = new TodoService();

// MapGroup: state the common prefix once instead of six times.
var todos = app.MapGroup("/todos");

todos.MapGet("/", (string? filter) => service.Filter(filter));

todos.MapGet("/{id:int}", (int id) =>
    service.Get(id) is Todo t ? Results.Ok(t) : Results.NotFound());

todos.MapPost("/", (CreateTodo body) =>
    service.Add(body.Title) is Todo t
        ? Results.Created($"/todos/{t.Id}", t)
        : Results.BadRequest(new { error = "title must not be empty" }));

todos.MapPut("/{id:int}", (int id, UpdateTodo body) =>
    service.Get(id) is null ? Results.NotFound()
    : service.Update(id, body.Title, body.Done) is Todo t ? Results.Ok(t)
    : Results.BadRequest(new { error = "title must not be empty" }));

todos.MapPost("/{id:int}/toggle", (int id) =>
    service.Toggle(id) is Todo t ? Results.Ok(t) : Results.NotFound());

todos.MapDelete("/{id:int}", (int id) =>
    service.Remove(id) ? Results.NoContent() : Results.NotFound());

app.Run("http://localhost:5015");

// Tests.cs — tests the DECISIONS (TodoService) without any HTTP at all.
// The original could not be tested this way: its logic only existed inside
// endpoint lambdas, reachable only by booting a server and sending requests.
public static class Tests
{
    public static int Run()
    {
        Console.WriteLine("TodoService.Add");
        {
            var svc = new TodoService();
            var t = svc.Add("buy milk");
            Check.True(t is not null, "a valid title creates a todo");
            Check.Equal(1, t!.Id, "the first todo gets id 1");
            Check.Equal("buy milk", t.Title, "the title is stored");
            Check.Equal(false, t.Done, "new todos start not-done");
            Check.Equal(2, svc.Add("walk dog")!.Id, "ids count up");
            Check.Equal(null, svc.Add(""), "an empty title is rejected");
            Check.Equal(null, svc.Add("   "), "a whitespace-only title is rejected");
            Check.Equal(null, svc.Add(null), "a missing title is rejected");
            Check.Equal("trimmed", svc.Add("  trimmed  ")!.Title, "titles are trimmed");
            Check.Equal(3, svc.All().Count, "rejected todos were never added");
        }

        Console.WriteLine("TodoService.Get / Toggle / Remove");
        {
            var svc = new TodoService();
            var a = svc.Add("a")!;
            Check.Equal(a, svc.Get(a.Id), "Get finds a todo by id (records compare by value, cs#07)");
            Check.Equal(null, svc.Get(999), "Get returns null for unknown ids");
            Check.Equal(true, svc.Toggle(a.Id)!.Done, "Toggle flips done to true");
            Check.Equal(false, svc.Toggle(a.Id)!.Done, "Toggle flips it back to false");
            Check.Equal(null, svc.Toggle(999), "Toggle returns null for unknown ids");
            Check.True(svc.Remove(a.Id), "Remove returns true when it deletes");
            Check.Equal(0, svc.All().Count, "the removed todo is gone");
            Check.True(!svc.Remove(a.Id), "Remove returns false the second time");
        }

        Console.WriteLine("TodoService.Update");
        {
            var svc = new TodoService();
            var a = svc.Add("old title")!;
            var updated = svc.Update(a.Id, "new title", done: true);
            Check.Equal("new title", updated!.Title, "Update replaces the title");
            Check.Equal(true, updated.Done, "Update sets done");
            Check.Equal(null, svc.Update(a.Id, "", done: false), "an empty title is rejected");
            Check.Equal("new title", svc.Get(a.Id)!.Title, "a rejected update changed nothing");
            Check.Equal(null, svc.Update(999, "x", done: false), "unknown ids return null");
        }

        Console.WriteLine("TodoService.Filter");
        {
            var svc = new TodoService();
            svc.Add("a"); svc.Add("b"); svc.Add("c");
            svc.Toggle(2);
            Check.Equal(3, svc.Filter(null).Count, "no filter returns everything");
            Check.Equal(1, svc.Filter("done").Count, "filter=done returns only finished todos");
            Check.Equal("b", svc.Filter("done")[0].Title, "and it is the one we toggled");
            Check.Equal(2, svc.Filter("open").Count, "filter=open returns only unfinished todos");
            Check.Equal(3, svc.Filter("banana").Count, "an unknown filter returns everything");
        }

        return Check.Summary();
    }
}

// The shape of our data, stated once. Compare with the original's
// Dictionary<string, object>, where every endpoint had to *remember* the keys.
// A record (cs#07) gives us value equality and non-destructive `with` updates.
public record Todo(int Id, string Title, bool Done);

// DTOs ("data transfer objects"): the shapes clients are allowed to send us.
// Title is string? because a client might omit it — validation decides.
public record CreateTodo(string? Title);
public record UpdateTodo(string? Title, bool Done);

// TodoService — ALL the decisions, ZERO HTTP. This class never sees a request,
// a response, or a status code, which is exactly why Tests.cs can exercise
// every rule by calling plain methods. (Same move as js#65's service layer.)
public class TodoService
{
    private readonly List<Todo> _todos = new();
    private int _nextId = 1;

    public IReadOnlyList<Todo> All() => _todos;

    public IReadOnlyList<Todo> Filter(string? filter) => filter switch
    {
        "done" => _todos.Where(t => t.Done).ToList(),
        "open" => _todos.Where(t => !t.Done).ToList(),
        _ => _todos.ToList(),   // unknown or missing filter: everything
    };

    public Todo? Get(int id) => _todos.FirstOrDefault(t => t.Id == id);

    /// Returns the new todo, or null if the title is missing/blank.
    public Todo? Add(string? title)
    {
        if (string.IsNullOrWhiteSpace(title)) return null;
        var todo = new Todo(_nextId++, title.Trim(), Done: false);
        _todos.Add(todo);
        return todo;
    }

    /// Returns the updated todo, or null if the id is unknown OR the title is blank.
    public Todo? Update(int id, string? title, bool done)
    {
        if (string.IsNullOrWhiteSpace(title)) return null;
        var index = _todos.FindIndex(t => t.Id == id);
        if (index < 0) return null;
        _todos[index] = _todos[index] with { Title = title.Trim(), Done = done };
        return _todos[index];
    }

    /// Flips Done. Returns the updated todo, or null if the id is unknown.
    public Todo? Toggle(int id)
    {
        var index = _todos.FindIndex(t => t.Id == id);
        if (index < 0) return null;
        _todos[index] = _todos[index] with { Done = !_todos[index].Done };
        return _todos[index];
    }

    /// True if something was actually removed.
    public bool Remove(int id) => _todos.RemoveAll(t => t.Id == id) > 0;
}
